// Analyze the test file to understand string expectations
// Read the test file and print what each string literal actually represents

const fs = require('fs');
const content = fs.readFileSync('src/pathstringifier.test.ts', 'utf8');

function showStr(s) {
  const chars = [...s].map(c => c.charCodeAt(0));
  const display = s.split('').map(c => {
    if (c === '\\') return '\\\\';
    return c;
  }).join('');
  return JSON.stringify(s) + ' [' + chars.join(',') + ']';
}

console.log('=== New mode parsePath tests ===');
