export const parsePath = (string: StringifiedPath, isLegacy = true) => {
  const result: string[] = [];

  let segment = '';
  for (let i = 0; i < string.length; i++) {
    let char = string.charAt(i);

    if (char === '\\') {
      const next = string.charAt(i + 1);
      if (isLegacy) {
        // Legacy mode: only \. is special (escaped dot)
        if (next === '.') {
          segment += '.';
          i++;
          continue;
        }
      } else {
        // New mode: \. is escaped dot, \\ is two literal backslashes
        if (next === '.') {
          segment += '.';
          i++;
          continue;
        } else if (next === '\\') {
          segment += '\\';
          i++;
          continue;
        } else {
          throw new Error(`Invalid path string: ${string}`);
        }
      }
    }

    const isEndOfSegment = char === '.';
    if (isEndOfSegment) {
      result.push(segment);
      segment = '';
      continue;
    }

    segment += char;
  }

  const lastSegment = segment;
  result.push(lastSegment);

  return result;
};

